--
-- 38_菜式库扩充_v1.2r2.sql
-- 用途：按团队分工（陈媛-数据）把菜式库由 60 道扩充到约 120 道，本批新增 DISH-061..120 共 60 道，含主食池补充；
--       配料全部复用 core.ingredient 现有 128 种；本批未反推新增食材。
-- 口径：单人份低油低盐家常搭配；source='家常菜库（v1.2r2 扩充批次）'，source_id='home-dishes-zh-cn-v2'，data_quality=approx；
--       营养快照由 app.v_dish_live_nutrition 按 core.ingredient × amount_g 重算，缺失营养值保持 NULL，不按 0 计算。
-- 前置：01 备份还原且已跑完既有迁移链；core.dish / core.dish_ingredient / core.ingredient 已存在。
-- 执行账号：postgres（diet_app 无 core 写权限）。幂等：ON CONFLICT 覆盖描述性字段，重复执行不新增重复行。
-- 边界：本脚本只补菜式与配料关系；微量/宏量营养素细项、做法步骤文本与 data_quality 复核归另一数据岗。
--

\set ON_ERROR_STOP on
\pset pager off

DO $$
DECLARE v_has_table boolean; v_can_write boolean;
BEGIN
  v_has_table := to_regclass('core.dish') IS NOT NULL AND to_regclass('core.dish_ingredient') IS NOT NULL AND to_regclass('core.ingredient') IS NOT NULL;
  IF NOT v_has_table THEN RAISE EXCEPTION 'core.dish / dish_ingredient / ingredient 未建：先还原 01 备份并跑完既有迁移链，再跑本脚本'; END IF;
  v_can_write := has_table_privilege(current_user,'core.dish','INSERT') AND has_table_privilege(current_user,'core.dish_ingredient','INSERT');
  IF NOT v_can_write THEN RAISE EXCEPTION '当前用户 % 对 core 无 INSERT 权限，请换 postgres 执行：psql -U postgres -d diet_agent -f 本脚本', current_user; END IF;
END $$;

-- 0. 登记本批导入批次（幂等）
INSERT INTO audit.import_batch
  (import_batch_id, dataset_name, dataset_version, original_file_name, original_sha256, imported_at, imported_by, status, notes)
VALUES
  (4, '菜式库扩充 60→约120', 'v1.2r2-2026-11-19', '20_菜式库扩充清单_v1.2r2.csv', '', now(), 'chenyuan', 'promoted',
   '新增 DISH-061..120 共 60 道（含主食 8 道）；配料复用现有 128 种食材，未反推新增食材；营养快照由 core.ingredient 按克数重算。')
ON CONFLICT (import_batch_id) DO NOTHING;
SELECT setval('audit.import_batch_import_batch_id_seq', COALESCE((SELECT max(import_batch_id) FROM audit.import_batch), 0));

